subsection.example:
#include "global.h"
#include "module.h"
#include "interpret.h"
#include "pike_types.h"
#include "module_support.h"

static void f_is_positive(INT32 args)
{
  INT_TYPE value;

  if (args != 1)
    Pike_error("Example.is_positive(): Expected one argument.\n");

  get_all_args("Example.is_positive", args, "%i", &value);
  pop_n_elems(args);
  push_int(value > 0);
}

PIKE_MODULE_INIT
{
  ADD_FUNCTION("is_positive", f_is_positive, tFunc(tInt, tInt), 0);
  ADD_INT_CONSTANT("API_VERSION", 1, 0);
}

PIKE_MODULE_EXIT
{
  /* No module-wide resources to release. */
}

#include "global.h"
#include "module.h"
#include "interpret.h"
#include "pike_types.h"
#include "module_support.h"

DECLARATIONS

/*! @module Example */

/*! @decl int is_positive(int value)
 *! Returns 1 if the native integer value is positive, otherwise 0.
 */
PIKEFUN int is_positive(int value)
{
  RETURN value > 0;
}

/*! @endmodule */

PIKE_MODULE_INIT
{
  INIT
  ADD_INT_CONSTANT("API_VERSION", 1, 0);
}

PIKE_MODULE_EXIT
{
  EXIT
}

/*! @class Flag */
PIKECLASS Flag
{
  CVAR int enabled;

  INIT
  {
    THIS->enabled = 0;
  }

  /*! @decl int set(int enabled)
   *! Sets the flag and returns its new value, either 0 or 1.
   */
  PIKEFUN int set(int enabled)
  {
    THIS->enabled = enabled != 0;
    RETURN THIS->enabled;
  }

  /*! @decl int get()
   *! Returns the current value of the flag.
   */
  PIKEFUN int get()
  {
    RETURN THIS->enabled;
  }
}
/*! @endclass */
